def check_type(t):
    # Check if tuple has at least one element to avoid errors on empty tuples
    if len(t) == 0:
        return False

    # Get the type of the first element as a reference
    ref_type = type(t[0])

    # Iterate through all elements and compare their types with the reference
    for item in t:
        if not isinstance(item, ref_type):
            return False

    return True

# Test cases based on your requirement
if __name__ == "__main__":
    assert check_type((5, 6, 7, 3, 5, 6)) == True   # All are int -> Passes
print("Test passed!")

# Additional test to ensure it catches different types
try:
    assert check_type((1, "2", 3.0)) == False 
except AssertionError:
    print("Correctly identified mixed types.")

